// Generated by scripts/sync-core.mjs from Nexora-Saas src/lib/platform/console-inbox.ts. Do not edit: change the web repository and run npm run sync:core.
import { consoleCan } from "./console-roles"
import { sessionState } from "./session-policy"
import { ConsoleCapability as C, ConsoleRole, type StaffSession, type PlatformStaff } from "../../types/platform-console"
import type { CustomerAccount } from "../../types/platform-customers"
import type { NxInvoice, NxPayment, NxRefund, ReconciliationRun } from "../../types/platform-billing"
import type { SupportRequest } from "../../types/platform-support"
import type { Incident, ServiceHealth } from "../../types/platform-ops"
import type { DataRequest } from "../../types/platform-data"
import type { InboxItem } from "../workforce/inbox"

/**
 * The Nexora team's bell (§11.2), built like the companies' work inbox: what
 * is waiting for the signed-in member, by role, with where to act. Approvers
 * never see their own requests. Pure, so the server sends the same alerts.
 */

const countryOf = (location: string) => location.split(",").pop()?.trim() ?? location

/** SEC-13: a session from a browser or a country the member never used before. */
export function isNewDevice(s: Pick<StaffSession, "id" | "staffId" | "device" | "location" | "startedAt">, all: Pick<StaffSession, "id" | "staffId" | "device" | "location" | "startedAt">[]) {
  const before = all.filter((x) => x.staffId === s.staffId && x.id !== s.id && x.startedAt < s.startedAt)
  if (before.length === 0) return false
  return !before.some((x) => x.device === s.device && countryOf(x.location) === countryOf(s.location))
}

export interface ConsoleInboxInput {
  me: { id: string; name: string; role: ConsoleRole }
  staff: PlatformStaff[]
  sessions: StaffSession[]
  support: SupportRequest[]
  refunds: NxRefund[]
  requests: DataRequest[]
  invoices: NxInvoice[]
  payments: NxPayment[]
  reconciliations: ReconciliationRun[]
  health: ServiceHealth[]
  incidents: Incident[]
  customers: CustomerAccount[]
  today: string
  now?: Date
}

const daysUntil = (iso: string, today: string) => Math.round((new Date(`${iso.slice(0, 10)}T00:00:00Z`).getTime() - new Date(`${today}T00:00:00Z`).getTime()) / 86_400_000)

export function buildConsoleInbox(d: ConsoleInboxInput): InboxItem[] {
  const role = d.me.role
  const items: InboxItem[] = []
  const add = (i: InboxItem) => items.push(i)

  // support: urgent requests and new ones nobody picked up
  if ([ConsoleRole.OWNER, ConsoleRole.ADMIN, ConsoleRole.SUPPORT].includes(role)) {
    const open = d.support.filter((r) => r.status === "open")
    const urgent = open.filter((r) => r.priority === "urgent")
    for (const r of urgent) add({ id: `sup-urgent:${r.id}`, category: "system", title: "cinUrgent", message: "cinUrgentMessage", values: { number: r.number, company: r.customerName, subject: r.subject }, href: "/dashboard/support-desk" })
    const unassigned = open.filter((r) => !r.assigneeId && r.priority !== "urgent")
    if (unassigned.length) add({ id: `sup-new:${unassigned.map((r) => r.id).join(",")}`, category: "team", title: "cinUnassigned", message: "cinUnassignedMessage", values: { count: unassigned.length }, href: "/dashboard/support-desk" })
    const mine = open.filter((r) => r.assigneeId === d.me.id && r.messages.at(-1)?.side === "customer")
    if (mine.length) add({ id: `sup-mine:${mine.map((r) => `${r.id}${r.messages.length}`).join(",")}`, category: "team", title: "cinMyReplies", message: "cinMyRepliesMessage", values: { count: mine.length }, href: "/dashboard/support-desk" })
  }

  // approvals waiting for this member (never their own)
  if (consoleCan(role, C.REFUND_LARGE)) {
    const waiting = d.refunds.filter((r) => r.status === "awaiting_approval" && r.requestedBy !== d.me.name)
    if (waiting.length) add({ id: `refunds:${waiting.map((r) => r.id).join(",")}`, category: "billing", title: "cinRefunds", message: "cinRefundsMessage", values: { count: waiting.length, amount: Math.round(waiting.reduce((s, r) => s + r.amount, 0)) }, href: "/dashboard/transactions" })
  }
  if (consoleCan(role, C.DELETE_CUSTOMER)) {
    for (const r of d.requests.filter((x) => x.kind === "deletion" && x.status === "prepared" && x.preparedBy !== d.me.name)) {
      add({ id: `deletion:${r.id}`, category: "security", title: "cinDeletion", message: "cinDeletionMessage", values: { company: r.customerName, name: r.preparedBy ?? "—" }, href: "/dashboard/data-requests" })
    }
  }
  if (consoleCan(role, C.CHANGE_STATUS)) {
    const toDo = d.requests.filter((x) => x.status === "received")
    const late = toDo.filter((x) => x.dueOn < d.today)
    if (toDo.length) add({ id: `data:${toDo.map((r) => r.id).join(",")}`, category: late.length ? "security" : "team", title: late.length ? "cinDataLate" : "cinData", message: "cinDataMessage", values: { count: toDo.length, late: late.length }, href: "/dashboard/data-requests" })
  }

  // money: failed renewals, transfers to match, reconciliation differences
  if (consoleCan(role, C.CREDIT_NOTES) || consoleCan(role, C.CHANGE_SUBSCRIPTION)) {
    const overdue = d.invoices.filter((i) => i.status === "overdue")
    if (overdue.length) add({ id: `overdue:${overdue.map((i) => i.id).join(",")}`, category: "billing", title: "cinOverdue", message: "cinOverdueMessage", values: { count: overdue.length, amount: Math.round(overdue.reduce((s, i) => s + i.total - i.paid - i.credited, 0)) }, href: "/dashboard/transactions" })
  }
  if (consoleCan(role, C.CREDIT_NOTES)) {
    const queue = d.payments.filter((p) => p.status === "unmatched")
    if (queue.length) add({ id: `queue:${queue.map((p) => p.id).join(",")}`, category: "billing", title: "cinTransfers", message: "cinTransfersMessage", values: { count: queue.length }, href: "/dashboard/transactions" })
    const last = [...d.reconciliations].sort((a, b) => b.createdAt.localeCompare(a.createdAt))[0]
    if (last && last.differences.length) add({ id: `rec:${last.id}`, category: "billing", title: "cinReconciliation", message: "cinReconciliationMessage", values: { count: last.differences.length, day: last.day }, href: "/dashboard/reconciliation" })
  }

  // platform: failing services and incident drafts
  if (consoleCan(role, C.INCIDENTS)) {
    const failing = d.health.filter((h) => h.state !== "ok")
    if (failing.length) add({ id: `health:${failing.map((h) => `${h.service}${h.state}`).join(",")}`, category: "system", title: "cinHealth", message: "cinHealthMessage", values: { count: failing.length }, href: "/dashboard/health" })
    const drafts = d.incidents.filter((i) => i.kind === "incident" && i.status === "draft")
    if (drafts.length) add({ id: `drafts:${drafts.map((i) => i.id).join(",")}`, category: "system", title: "cinDrafts", message: "cinDraftsMessage", values: { count: drafts.length }, href: "/dashboard/incidents" })
  }

  // customers: trials ending in 3 days or less, companies with every seat used
  if (consoleCan(role, C.CREATE_TRIAL)) {
    const ending = d.customers.filter((c) => c.status === "trial" && c.trialEndsOn && daysUntil(c.trialEndsOn, d.today) >= 0 && daysUntil(c.trialEndsOn, d.today) <= 3)
    for (const c of ending) add({ id: `trial:${c.id}:${c.trialEndsOn}`, category: "team", title: "cinTrial", message: "cinTrialMessage", values: { company: c.name, days: daysUntil(c.trialEndsOn!, d.today) }, href: `/dashboard/platform/${c.id}` })
  }
  if (consoleCan(role, C.CHANGE_SUBSCRIPTION) || consoleCan(role, C.CREATE_TRIAL)) {
    for (const c of d.customers.filter((x) => x.seatsFullNotice)) add({ id: `seats:${c.id}:${c.seatsFullNotice!.period}`, category: "team", title: "cinSeats", message: "cinSeatsMessage", values: { company: c.name, limit: c.seatsFullNotice!.limit }, href: `/dashboard/platform/${c.id}` })
  }

  // SEC-13: the owner hears about sign-ins from a new device or country
  if (role === ConsoleRole.OWNER) {
    const now = d.now ?? new Date()
    for (const s of d.sessions) {
      if (s.staffId === d.me.id || sessionState(s, now) !== "active" || !isNewDevice(s, d.sessions)) continue
      const who = d.staff.find((x) => x.id === s.staffId)?.name ?? "—"
      add({ id: `device:${s.id}`, category: "security", title: "cinDevice", message: "cinDeviceMessage", values: { name: who, device: s.device, location: s.location }, href: "/dashboard/sessions" })
    }
  }
  return items
}
